'use strict';

const path = require('path');
const cds = require('@sap/cds');

const files = require('./utils/files');

function setup() {
  const allRules = loadRules();
  if (!allRules) return { error: 'Failed to load migration rules' };

  const languages = detectLanguages();
  const rules = filterRulesByRuntime(allRules, languages);
  const projectFiles = files.discoverProjectFiles(cds.root);
  const nonSourceFiles = [...projectFiles.config, ...projectFiles.other];
  const fileCache = files.buildFileCache([projectFiles.cdl, projectFiles.source, nonSourceFiles]);

  return {
    rules,
    languages,
    projectFiles,
    fileCache,
    nonSourceFiles,
  };
}

function filterRulesByRuntime(rules, languages) {
  const runtimes = new Set(languages.map(l => l === 'java' ? 'java' : 'nodejs'));
  return rules.filter(rule => runtimes.has(rule.runtime || 'nodejs'));
}

function loadRules() {
  const fs = cds.utils.fs;
  const bundlePath = path.join(__dirname, '..', '..', 'migrations', 'cds10', 'migrations.json');
  try {
    const bundle = JSON.parse(fs.readFileSync(bundlePath, 'utf8'));
    return bundle.entries;
  } catch {
    return null;
  }
}

function detectLanguages() {
  const exists = cds.utils.exists;
  const pkg = readRootPackage();
  const allDeps = { ...pkg.dependencies, ...pkg.devDependencies };
  const isJavaProject = exists(path.join(cds.root, 'pom.xml'));
  const isNodeProject = exists(path.join(cds.root, 'package.json')) && (!isJavaProject || !!allDeps['@sap/cds']);
  const isTypeScript = !!allDeps['typescript'] || exists(path.join(cds.root, 'tsconfig.json'));

  const languages = [];
  if (isNodeProject) languages.push(isTypeScript ? 'ts' : 'js');
  if (isJavaProject) languages.push('java');
  if (languages.length === 0) languages.push('js');
  return languages;
}

function readRootPackage() {
  const fs = cds.utils.fs;
  const exists = cds.utils.exists;
  const pkgPath = path.join(cds.root, 'package.json');
  if (!exists(pkgPath)) return {};
  try { return JSON.parse(fs.readFileSync(pkgPath, 'utf8')); } catch { return {}; }
}

module.exports = {
  setup,
  loadRules,
  detectLanguages,
  filterRulesByRuntime,
};
